def clean(ax):
    ax.set_facecolor(PAPER)
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)
    ax.spines["left"].set_color(INK)
    ax.spines["bottom"].set_color(INK)
    ax.tick_params(colors=INK, pad=1.4)


def panel_letter(fig, x, y, s):
    fig.text(x, y, s, ha="left", va="top", fontsize=9.2, fontweight="bold", color=INK)


def paired_cell(ax, cx, cy, a, b, *, vmin, vmax, width=0.78, dy=0.12, marker_size=10):
    HEST_PAIRS.append((float(a), float(b), vmin, vmax))
    left = cx - width / 2 + 0.06
    span = width - 0.12
    xa = left + np.clip((a - vmin) / (vmax - vmin), 0, 1) * span
    xb = left + np.clip((b - vmin) / (vmax - vmin), 0, 1) * span
    col = PETROL if b >= a else NEG
    ax.plot([xa, xb], [cy + dy, cy - dy], color=col, lw=0.62, alpha=0.72, zorder=2)
    ax.scatter(xa, cy + dy, s=marker_size, marker="o", facecolor=PAPER, edgecolor=MID, linewidth=0.55, zorder=3)
    ax.scatter(xb, cy - dy, s=marker_size, marker="s", facecolor=PETROL, edgecolor=PETROL_DARK, linewidth=0.35, zorder=4)


def local_ruler(ax, cx, y, vmin, vmax, *, width, ticks, size=6.1):
    """The same affine map as the marks, so every common numeric tick is exact."""
    left = cx - width / 2 + 0.06
    span = width - 0.12
    ax.plot([left, left+span], [y, y], color=MID, lw=0.45, clip_on=False, zorder=1)
    for value in ticks:
        x = left + (value-vmin)/(vmax-vmin)*span
        ax.plot([x,x], [y,y-0.08], color=MID, lw=0.45, clip_on=False, zorder=1)
        ax.text(x,y-0.11,f"{value:g}",ha="center",va="top",color=INK,
                fontsize=size,clip_on=False,zorder=10)


