def endpoint_panel(rect, df, title, xlim, xlabel, letter, *, show_means=False, zero=False):
    ax=fig.add_axes(rect); clean(ax); ax.set_xlim(*xlim); ax.set_ylim(-0.75,5.88)
    if zero: ax.axvline(0,color=MID,lw=0.65,ls=(0,(2.5,2.3)),zorder=0)
    ax.set_yticks(range(6)); ax.set_yticklabels(["P5","P4","P3","P2","P1","Mean"])
    ax.grid(axis="x",color=RULE,lw=0.45,zorder=0)
    vals=[]
    for pi,patient in enumerate(PATIENTS):
        r=df[df.patient==patient].iloc[0]
        a=float(r.resnet50); b=float(r.phikon_v2); y=4-pi
        ax.plot([a,b],[y,y],color=PETROL if b>=a else NEG,lw=0.82,alpha=0.84)
        ax.scatter(a,y,s=16,marker="o",facecolor=PAPER,edgecolor=MID,linewidth=0.62,zorder=3)
        ax.scatter(b,y,s=16,marker="s",facecolor=PETROL,edgecolor=PETROL_DARK,linewidth=0.40,zorder=4)
        vals.append((a,b))
    ma=float(np.mean([v[0] for v in vals])); mb=float(np.mean([v[1] for v in vals]))
    ax.plot([ma,mb],[5,5],color=PETROL if mb>=ma else NEG,lw=1.25)
    ax.scatter(ma,5,s=28,marker="D",facecolor=PAPER,edgecolor=MID,linewidth=0.75,zorder=3)
    ax.scatter(mb,5,s=28,marker="D",facecolor=PETROL,edgecolor=PETROL_DARK,linewidth=0.48,zorder=4)
    if show_means:
        ax.text(ma,5.47,f"{ma:.5f}",ha="right",va="bottom",color=MID,fontsize=6.5)
        ax.text(mb,5.47,f"{mb:.5f}",ha="left",va="bottom",color=PETROL_DARK,fontsize=6.5)
        ax.text((ma+mb)/2,4.60,f"Δ {mb-ma:+.5f}",ha="center",va="top",color=PETROL_DARK,fontsize=6.5)
    ax.set_title(title,loc="left",pad=7,fontweight="semibold")
    ax.set_xlabel(xlabel)
    panel_letter(fig,rect[0]-0.080,rect[1]+rect[3]+0.020,letter)
    return ax


