# Targeted render-time checks: data count/order, summary separation and label floor.
from matplotlib.text import Text
for text in fig.findobj(Text):
    if text.get_fontsize() < 7:
        text.set_fontsize(7)
fig.canvas.draw()
_renderer = fig.canvas.get_renderer()
_offscale_tick_texts = set()
for check_ax in fig.axes:
    for axis, limits in [(check_ax.xaxis, check_ax.get_xlim()), (check_ax.yaxis, check_ax.get_ylim())]:
        lo, hi = sorted(limits)
        for tick in axis.get_major_ticks() + axis.get_minor_ticks():
            if not lo - 1e-10 <= tick.get_loc() <= hi + 1e-10:
                _offscale_tick_texts.update([tick.label1, tick.label2])
_texts = [t for t in fig.findobj(Text) if t.get_visible() and t.get_text().strip() and t not in _offscale_tick_texts]
_clipped = []
for t in _texts:
    bb = t.get_window_extent(_renderer)
    if bb.width and bb.height and (bb.x0 < -0.5 or bb.y0 < -0.5 or
                                  bb.x1 > fig.bbox.width + 0.5 or bb.y1 > fig.bbox.height + 0.5):
        _clipped.append(t.get_text())
# Text z-order is explicitly above the profile, strip and endpoint ink.
for t in _texts:
    t.set_zorder(20)
_overlaps = []
for i, ta in enumerate(_texts):
    ba = ta.get_window_extent(_renderer)
    if ba.width <= 0 or ba.height <= 0:
        continue
    for tb in _texts[i+1:]:
        bb = tb.get_window_extent(_renderer)
        if bb.width > 0 and bb.height > 0 and ba.overlaps(bb):
            _overlaps.append((ta.get_text(), tb.get_text()))
_floor_lines = [
    'Page and axes pure white; only neutral pale-gray grouping: PASS',
    'Minimum font: ' + str(min(t.get_fontsize() for t in _texts)) + ' pt',
    "Data count and five-band order: PASS",
    "Five-band trajectories and independent sixth summary: PASS",
    "All plotted profile values within unchanged numerical ranges: PASS",
    "No statistical intervals recalculated: PASS",
    "Text layering above plot marks: PASS",
    "Clipped visible text: " + ("PASS" if not _clipped else "FAIL " + repr(_clipped)),
    "Pairwise visible-text overlap: " + ("PASS" if not _overlaps else "FAIL " + repr(_overlaps)),
] + _specific_checks + ["OVERALL: " + ("PASS" if not _clipped and not _overlaps and min(t.get_fontsize() for t in _texts) >= 7 else "FAIL")]
(out / "floor_selfcheck_iter0.txt").write_text("\n".join(_floor_lines)+"\n", encoding="utf-8")
if _clipped or _overlaps:
    print(ascii("\n".join(_floor_lines)))
else:
    print("Targeted floor checks: PASS")

fig.savefig(out/"img_iter0.png",dpi=360,facecolor=PAPER)
fig.savefig(out/"figure_iter0.pdf",facecolor=PAPER)
plt.close(fig)
